package com.witchersbestiary.sorcery;
import java.util.*;import com.witchersbestiary.signs.SignManager;import net.minecraft.entity.*;import net.minecraft.entity.effect.*;import net.minecraft.entity.projectile.ProjectileUtil;import net.minecraft.entity.damage.*;import net.minecraft.item.*;import net.minecraft.registry.*;import net.minecraft.registry.tag.TagKey;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.util.*;import net.minecraft.particle.*;import net.minecraft.sound.*;import net.minecraft.text.Text;import net.fabricmc.fabric.api.networking.v1.*;import net.fabricmc.fabric.api.event.lifecycle.v1.*;
/** One spell, one vanilla item cost; no parallel mana or sign concentration system. */
public final class Sorcery {
 public static final RegistryKey<DamageType> DAMAGE=RegistryKey.of(RegistryKeys.DAMAGE_TYPE,Identifier.of("witchersbestiary:icy_grasp"));
 private static final class Runtime {UUID session=UUID.randomUUID();long sequence=-1;int requests,window;}
 private static final Map<UUID,Runtime> ACTIVE=new HashMap<>();
 private record Freeze(RegistryKey<net.minecraft.world.World> dimension,long until){}
 private static final Map<UUID,Freeze> FROZEN=new HashMap<>();
 public static SorceryLedger.Progress state(ServerPlayerEntity p){return SorceryLedger.get(p.getServer()).player(p.getUuid());}
 private static Runtime runtime(ServerPlayerEntity p){return ACTIVE.computeIfAbsent(p.getUuid(),k->new Runtime());}
 public static boolean hasBook(ServerPlayerEntity p){for(int i=0;i<p.getInventory().size();i++)if(p.getInventory().getStack(i).isOf(com.witchersbestiary.registry.ModItems.GRIMOIRE))return true;return false;}
 public static boolean learn(ServerPlayerEntity p){if(!hasBook(p)||!p.isAlive()||p.isSpectator())return false;state(p).learned=true;SorceryLedger.get(p.getServer()).markDirty();sync(p);return true;}
 public static void intent(ServerPlayerEntity p,SorceryPackets.Intent packet){var r=runtime(p);int now=p.getServer().getTicks();if(now-r.window>=20){r.window=now;r.requests=0;}if(++r.requests>8||!r.session.equals(packet.session())||packet.sequence()<=r.sequence)return;r.sequence=packet.sequence();if(packet.action()==0)learn(p);else if(packet.action()==1)cast(p);}
 public static LivingEntity target(ServerPlayerEntity p){var from=p.getEyePos();var to=from.add(p.getRotationVec(1).multiply(12));var wall=p.raycast(12,1,false);double distance=from.squaredDistanceTo(wall.getPos());var hit=ProjectileUtil.raycast(p,from,to,p.getBoundingBox().stretch(p.getRotationVec(1).multiply(12)).expand(1),e->e instanceof LivingEntity living&&SignManager.enemy(p,living),distance);return hit!=null&&hit.getEntity() instanceof LivingEntity e&&p.canSee(e)&&from.squaredDistanceTo(hit.getPos())<=144?e:null;}
 public static boolean cast(ServerPlayerEntity p){var state=state(p);if(!SignManager.allowed(p)||!state.learned||state.cooldown>0||!hasBook(p))return false;var target=target(p);if(target==null)return fail(p,"target");var w=p.getServerWorld();var prior=FROZEN.get(target.getUuid());if(prior!=null&&prior.dimension()==w.getRegistryKey()&&prior.until()+80>w.getTime())return fail(p,"recovering");int slot=-1;for(int i=0;i<p.getInventory().size();i++)if(p.getInventory().getStack(i).isOf(Items.AMETHYST_SHARD)){slot=i;break;}if(slot<0&&!p.isCreative())return fail(p,"resource");
  var fallback=new DamageSource(w.getRegistryManager().get(RegistryKeys.DAMAGE_TYPE).entryOf(DAMAGE),p);if(!target.damage(SpellPowerBridge.source(p,fallback),SpellPowerBridge.amount(p)))return false;
  if(!p.isCreative())p.getInventory().getStack(slot).decrement(1);state.cooldown=160;SorceryLedger.get(p.getServer()).markDirty();int duration=target.getWidth()>1.5||target.getMaxHealth()>=200?20:60;
  if(!target.getType().isIn(SignManager.CONTROL_IMMUNE))target.addStatusEffect(new StatusEffectInstance(StatusEffects.SLOWNESS,duration,3));
  FROZEN.put(target.getUuid(),new Freeze(w.getRegistryKey(),w.getTime()+duration));var viewers=new HashSet<>(PlayerLookup.tracking(target));viewers.add(p);for(var viewer:viewers)if(ServerPlayNetworking.canSend(viewer,SorceryPackets.Effect.ID))ServerPlayNetworking.send(viewer,new SorceryPackets.Effect(target.getId(),duration));
  w.playSound(null,target.getBlockPos(),SoundEvents.BLOCK_AMETHYST_BLOCK_CHIME,SoundCategory.PLAYERS,.6f,.7f);p.swingHand(Hand.OFF_HAND,true);sync(p);return true;
 }
 private static boolean fail(ServerPlayerEntity p,String key){p.sendMessage(Text.translatable("sorcery.witchersbestiary."+key),true);return false;}
 public static void sync(ServerPlayerEntity p){if(ServerPlayNetworking.canSend(p,SorceryPackets.View.ID))ServerPlayNetworking.send(p,new SorceryPackets.View(runtime(p).session,state(p).learned,state(p).cooldown));}
 public static void initialize(){SorceryPackets.initialize();ServerPlayConnectionEvents.JOIN.register((h,s,server)->{ACTIVE.remove(h.player.getUuid());sync(h.player);});ServerPlayConnectionEvents.DISCONNECT.register((h,s)->{ACTIVE.remove(h.player.getUuid());SorceryLedger.get(s).markDirty();});net.fabricmc.fabric.api.entity.event.v1.ServerPlayerEvents.AFTER_RESPAWN.register((old,p,alive)->{ACTIVE.remove(p.getUuid());sync(p);});ServerLifecycleEvents.SERVER_STOPPED.register(s->{ACTIVE.clear();FROZEN.clear();});ServerTickEvents.END_SERVER_TICK.register(s->{for(var p:s.getPlayerManager().getPlayerList()){var value=state(p);if(value.cooldown>0){value.cooldown--;if(s.getTicks()%20==0)SorceryLedger.get(s).markDirty();}if(s.getTicks()%10==0)sync(p);}if(s.getTicks()%5==0)FROZEN.entrySet().removeIf(entry->{var f=entry.getValue();var w=s.getWorld(f.dimension());if(w==null)return true;var e=w.getEntity(entry.getKey());if(w.getTime()<=f.until()&&e!=null&&e.isAlive()){w.spawnParticles(ParticleTypes.SNOWFLAKE,e.getX(),e.getY()+.5,e.getZ(),3,e.getWidth()/2,.5,e.getWidth()/2,.025);}else if(w.getTime()-f.until()<5&&e!=null)w.spawnParticles(new BlockStateParticleEffect(ParticleTypes.BLOCK,net.minecraft.block.Blocks.PACKED_ICE.getDefaultState()),e.getX(),e.getY()+.5,e.getZ(),12,.4,.4,.4,.05);return f.until()+80<w.getTime();});});}
}
